<?php
require_once __DIR__ . '/benefit_releases.php';
$role = $_SESSION['role'] ?? ''; $me = (int) ($_SESSION['user_id'] ?? 0);
$where = "(a.Status = 'Approved' OR ba.BenefitAccountID IS NOT NULL)"; $params = [];
if ($role === 'Internal_Admin') $where .= " AND (creator.Role IS NULL OR creator.Role IN ('Internal_Admin','Super_Admin'))";
elseif ($role === 'External_Admin') { $where .= ' AND s.CreatedBy = ?'; $params[] = $me; }
$stmt = $pdo->prepare("
    SELECT a.ApplicationID, a.UserID, a.Status AS ApplicationStatus, u.StudentID_Num, u.FirstName, u.LastName, u.Major,
           s.Name AS ScholarshipName, s.AwardAmount, COALESCE(NULLIF(s.ReleaseFrequency,''),'Per Semester') AS ScholarshipFrequency,
           ba.BenefitAccountID, COALESCE(ba.TotalEntitlement,s.AwardAmount,0) AS TotalEntitlement,
           COALESCE(ba.ReleaseFrequency,s.ReleaseFrequency,'Per Semester') AS ReleaseFrequency, ba.Notes,
           COALESCE((SELECT SUM(br.Amount) FROM benefit_releases br WHERE br.ApplicationID=a.ApplicationID),0) AS ReleasedAmount
    FROM application a JOIN users u ON u.UserID=a.UserID JOIN scholarship s ON s.ScholarshipID=a.ScholarshipID
    LEFT JOIN users creator ON creator.UserID=s.CreatedBy
    LEFT JOIN scholar_benefit_accounts ba ON ba.ApplicationID=a.ApplicationID
    WHERE $where ORDER BY s.Name,u.LastName,u.FirstName
");
$stmt->execute($params); $scholars=$stmt->fetchAll(PDO::FETCH_ASSOC);
$releases=[];
if ($scholars) {
    $ids=array_map('intval',array_column($scholars,'ApplicationID'));
    $rs=$pdo->query("SELECT * FROM benefit_releases WHERE ApplicationID IN (".implode(',',$ids).") ORDER BY PaymentDate DESC,BenefitReleaseID DESC");
    foreach($rs->fetchAll(PDO::FETCH_ASSOC) as $release) $releases[(int)$release['ApplicationID']][]=$release;
}
$today=(new DateTime('today',new DateTimeZone('Asia/Manila')))->format('Y-m-d');
?>
<main class="flex-1 p-5 lg:p-10 lg:ml-72 bg-slate-50/50 min-h-screen">
    <header class="mb-8"><p class="text-xs font-black text-green-600 uppercase tracking-[0.25em]">Disbursement Ledger</p><h2 class="text-3xl lg:text-4xl font-black text-slate-900 mt-2">Scholarship Benefits</h2><p class="text-slate-500 font-medium mt-2">Record actual releases and monitor each scholar’s unpaid balance.</p></header>
    <?php if(isset($_SESSION['success'])):?><div class="bg-green-50 border border-green-200 text-green-700 p-4 rounded-2xl mb-6 font-bold"><?=htmlspecialchars($_SESSION['success']);unset($_SESSION['success']);?></div><?php endif;?>
    <?php if(isset($_SESSION['error'])):?><div class="bg-red-50 border border-red-200 text-red-700 p-4 rounded-2xl mb-6 font-bold"><?=htmlspecialchars($_SESSION['error']);unset($_SESSION['error']);?></div><?php endif;?>
    <?php if(!$scholars):?><div class="bg-white border border-slate-200 rounded-[2rem] p-12 text-center"><div class="text-4xl mb-4">💳</div><h3 class="text-xl font-black text-slate-900">No approved scholars</h3><p class="text-slate-500 mt-2">Approved scholars within your authority will appear here.</p></div><?php endif;?>
    <div class="space-y-7">
    <?php foreach($scholars as $scholar): $total=(float)$scholar['TotalEntitlement'];$released=(float)$scholar['ReleasedAmount'];$remaining=max(0,$total-$released);$percent=$total>0?min(100,($released/$total)*100):0; ?>
      <section class="bg-white border border-slate-200 rounded-[2rem] overflow-hidden shadow-sm">
        <div class="p-6 lg:p-8 border-b border-slate-100 flex flex-col xl:flex-row xl:items-center justify-between gap-5"><div><p class="text-[10px] font-black text-blue-600 uppercase tracking-widest"><?=htmlspecialchars($scholar['ScholarshipName'])?></p><h3 class="text-xl font-black text-slate-900 mt-1"><?=htmlspecialchars($scholar['FirstName'].' '.$scholar['LastName'])?></h3><p class="text-xs font-bold text-slate-400 mt-1"><?=htmlspecialchars($scholar['StudentID_Num']??'')?> · <?=htmlspecialchars($scholar['Major']??'')?></p></div><div class="grid grid-cols-3 gap-4 text-right"><div><p class="text-[9px] font-black text-slate-400 uppercase">Entitlement</p><p class="font-black text-slate-900">₱<?=number_format($total,2)?></p></div><div><p class="text-[9px] font-black text-slate-400 uppercase">Released</p><p class="font-black text-green-600">₱<?=number_format($released,2)?></p></div><div><p class="text-[9px] font-black text-slate-400 uppercase">Unpaid</p><p class="font-black text-amber-600">₱<?=number_format($remaining,2)?></p></div></div></div>
        <div class="h-2 bg-slate-100"><div class="h-full bg-green-500" style="width:<?=$percent?>%"></div></div>
        <div class="p-6 lg:p-8 grid xl:grid-cols-2 gap-8">
          <div class="space-y-6">
            <?php if($scholar['ApplicationStatus']==='Approved'):?>
            <form action="../actions/process_benefit_release.php" method="POST" class="p-5 bg-slate-50 rounded-2xl border border-slate-200"><input type="hidden" name="action" value="save_entitlement"><input type="hidden" name="application_id" value="<?=(int)$scholar['ApplicationID']?>"><h4 class="font-black text-sm text-slate-900 mb-4">Benefit Account</h4><div class="grid sm:grid-cols-2 gap-3"><div><label class="text-[10px] font-black uppercase text-slate-500">Total Entitlement *</label><input type="number" name="total_entitlement" min="0.01" step="0.01" required value="<?=number_format($total,2,'.','')?>" class="w-full mt-1 p-3 border border-slate-200 rounded-xl"></div><div><label class="text-[10px] font-black uppercase text-slate-500">Release Frequency</label><input value="<?=htmlspecialchars($scholar['ReleaseFrequency'])?>" disabled class="w-full mt-1 p-3 border border-slate-200 rounded-xl bg-slate-100"></div></div><label class="block text-[10px] font-black uppercase text-slate-500 mt-3">Notes</label><input name="notes" maxlength="500" value="<?=htmlspecialchars($scholar['Notes']??'')?>" placeholder="Optional entitlement notes" class="w-full mt-1 p-3 border border-slate-200 rounded-xl"><button class="mt-3 bg-slate-900 text-white px-5 py-3 rounded-xl font-black text-xs uppercase tracking-widest">Save Entitlement</button></form>
            <form action="../actions/process_benefit_release.php" method="POST" enctype="multipart/form-data" class="p-5 bg-green-50/50 rounded-2xl border border-green-200" onsubmit="return confirm('Record this actual scholarship benefit release?');"><input type="hidden" name="action" value="add_release"><input type="hidden" name="application_id" value="<?=(int)$scholar['ApplicationID']?>"><h4 class="font-black text-sm text-slate-900 mb-4">Record Actual Release</h4><div class="grid sm:grid-cols-2 gap-3"><div><label class="text-[10px] font-black uppercase text-slate-500">Amount *</label><input type="number" name="amount" min="0.01" max="<?=number_format($remaining,2,'.','')?>" step="0.01" required class="w-full mt-1 p-3 border border-slate-200 rounded-xl"></div><div><label class="text-[10px] font-black uppercase text-slate-500">Release Period *</label><input name="release_period" maxlength="100" required placeholder="e.g. 1st Sem AY 2026-2027" class="w-full mt-1 p-3 border border-slate-200 rounded-xl"></div><div><label class="text-[10px] font-black uppercase text-slate-500">Payment Date *</label><input type="date" name="payment_date" max="<?=$today?>" required class="w-full mt-1 p-3 border border-slate-200 rounded-xl"></div><div><label class="text-[10px] font-black uppercase text-slate-500">Mode *</label><select name="release_mode" required class="w-full mt-1 p-3 border border-slate-200 rounded-xl"><option value="">Select mode</option><option>Cash</option><option>Bank Transfer</option><option>Check</option><option>E-Wallet</option><option>Other</option></select></div><div><label class="text-[10px] font-black uppercase text-slate-500">Reference Number</label><input name="reference_number" maxlength="100" class="w-full mt-1 p-3 border border-slate-200 rounded-xl"></div><div><label class="text-[10px] font-black uppercase text-slate-500">Acknowledgement Receipt *</label><input type="file" name="acknowledgement_receipt" accept=".pdf,.jpg,.jpeg,.png" required class="w-full mt-1 p-3 border border-slate-200 rounded-xl text-xs"></div></div><button <?= $remaining<=0?'disabled':'' ?> class="mt-4 bg-green-600 disabled:bg-slate-300 text-white px-5 py-3 rounded-xl font-black text-xs uppercase tracking-widest">Record Release</button></form>
            <?php else:?><div class="p-5 bg-amber-50 border border-amber-200 rounded-2xl"><p class="font-black text-amber-800">Historical benefit account</p><p class="text-sm text-amber-700 mt-1">This application is <?=htmlspecialchars($scholar['ApplicationStatus'])?>. Previous releases remain visible, but new payments are disabled.</p></div><?php endif;?>
          </div>
          <div><h4 class="font-black text-sm text-slate-900 mb-4">Release History</h4><div class="space-y-3"><?php if(empty($releases[(int)$scholar['ApplicationID']])):?><div class="p-6 text-center border border-dashed border-slate-300 rounded-2xl text-sm text-slate-400">No benefit releases recorded yet.</div><?php endif;?><?php foreach($releases[(int)$scholar['ApplicationID']]??[] as $release):?><div class="p-4 border border-slate-200 rounded-2xl"><div class="flex justify-between gap-3"><div><p class="font-black text-slate-900">₱<?=number_format($release['Amount'],2)?></p><p class="text-xs font-bold text-slate-500 mt-1"><?=htmlspecialchars($release['ReleasePeriod'])?></p></div><span class="text-xs font-black text-green-700"><?=date('M d, Y',strtotime($release['PaymentDate']))?></span></div><div class="mt-3 flex flex-wrap gap-2 text-[10px] font-bold text-slate-500"><span class="px-2 py-1 bg-slate-100 rounded-lg"><?=htmlspecialchars($release['ReleaseMode'])?></span><?php if($release['ReferenceNumber']):?><span class="px-2 py-1 bg-slate-100 rounded-lg">Ref: <?=htmlspecialchars($release['ReferenceNumber'])?></span><?php endif;?><a target="_blank" href="<?=htmlspecialchars(benefitReceiptUrl($release['AcknowledgementReceipt']))?>" class="px-2 py-1 bg-blue-50 text-blue-700 rounded-lg">View Receipt</a></div></div><?php endforeach;?></div></div>
        </div>
      </section>
    <?php endforeach;?>
    </div>
</main>
